/**
 * LLM subprocess interface.
 * Spawns `claude` or `codex` CLI as a subprocess via execFile.
 * Uses temp files for prompts to avoid argument length limits and spawn bugs.
 */
import { execFile, spawn } from 'node:child_process';
const DEFAULT_TIMEOUT_MS = 120_000; // 2 minutes
/**
 * Check if a CLI binary is available on PATH.
 */
function which(name) {
    return new Promise((resolve) => {
        execFile('which', [name], (error) => {
            resolve(!error);
        });
    });
}
/**
 * Detect which LLM backend CLI is installed.
 * If `preferred` is specified and available, use it. Otherwise try both.
 */
export async function detectBackend(preferred) {
    if (preferred) {
        const available = await which(preferred);
        if (available)
            return preferred;
    }
    const [hasClaude, hasCodex] = await Promise.all([which('claude'), which('codex')]);
    if (hasClaude)
        return 'claude';
    if (hasCodex)
        return 'codex';
    throw new Error('No LLM CLI found. Install one of:\n' +
        '  - Claude Code: npm install -g @anthropic-ai/claude-code\n' +
        '  - Codex CLI: npm install -g @openai/codex');
}
/**
 * Call an LLM backend CLI and return the text output.
 * Writes the prompt to a temp file to avoid argument length limits.
 */
export async function callLlm(prompt, options) {
    const start = Date.now();
    const backend = options?.backend ?? await detectBackend();
    const timeout = options?.timeoutMs ?? DEFAULT_TIMEOUT_MS;
    // Strip CLAUDECODE env so nested claude doesn't detect it's inside Claude Code
    const cleanEnv = { ...process.env };
    delete cleanEnv.CLAUDECODE;
    delete cleanEnv.CLAUDE_CODE;
    const text = await new Promise((resolve, reject) => {
        if (backend === 'claude') {
            // Pipe prompt via stdin to avoid arg length limits
            const args = [
                '-p',
                '--output-format', 'text',
                '--tools', '',
                '--strict-mcp-config',
                '--system-prompt', 'You are a code generator. Output ONLY raw executable JavaScript code. No markdown fences, no explanations, no prose, no comments. Just code.',
            ];
            const child = spawn(backend, args, {
                stdio: ['pipe', 'pipe', 'pipe'],
                env: cleanEnv,
            });
            let stdout = '';
            let stderr = '';
            child.stdout.on('data', (d) => { stdout += d.toString(); });
            child.stderr.on('data', (d) => { stderr += d.toString(); });
            const timer = setTimeout(() => { child.kill(); reject(new Error('LLM timed out')); }, timeout);
            child.on('error', (err) => { clearTimeout(timer); reject(new Error(`${backend} CLI failed: ${err.message}`)); });
            child.on('close', (code) => {
                clearTimeout(timer);
                if (code !== 0) {
                    reject(new Error(`${backend} CLI failed: ${stderr.trim() || `exit code ${code}`}`));
                }
                else {
                    resolve(stdout);
                }
            });
            child.stdin.write(prompt);
            child.stdin.end();
        }
        else {
            execFile(backend, ['exec', '--skip-git-repo-check', prompt], { timeout, maxBuffer: 10 * 1024 * 1024, env: cleanEnv }, (error, stdout, stderr) => {
                if (error) {
                    reject(new Error(`${backend} CLI failed: ${stderr?.trim() || error.message}`));
                }
                else {
                    resolve(stdout);
                }
            });
        }
    });
    return {
        text: text.trim(),
        backend,
        durationMs: Date.now() - start,
    };
}
/**
 * Strip markdown code fences from LLM output.
 * Handles ```js, ```javascript, ```typescript, and plain ``` fences.
 * Falls back to extracting the first fenced block if the whole output isn't fenced.
 */
export function extractCode(raw) {
    const trimmed = raw.trim();
    // Match whole output wrapped in fences
    const fullMatch = trimmed.match(/^```(?:js|javascript|typescript|ts)?\s*\n?([\s\S]*?)```\s*$/);
    if (fullMatch) {
        return fullMatch[1].trim();
    }
    // Extract first fenced code block from mixed prose+code output
    const blockMatch = trimmed.match(/```(?:js|javascript|typescript|ts)?\s*\n([\s\S]*?)```/);
    if (blockMatch) {
        return blockMatch[1].trim();
    }
    // If no fences found, return as-is (LLM followed instructions)
    return trimmed;
}
